"use client";

import type { ComponentProps } from "react";

import { Shutter } from "@/components/shutter";

/** Porthole window with rim. Color: Classic. */
export function ShutterPortholeClassic(props: ComponentProps<typeof Shutter>) {
  return (
    <Shutter
      size="md"
      shape="porthole"
      defaultLevel={45}
      variant="classic"
      label="Porthole · Classic"
      {...props}
    />
  );
}
